import random
from src.fees import compute_fee

def test_fee_invariants():
    for _ in range(500):
        s = {"notional": random.uniform(100.0, 900000.0),
             "tier": random.choice(["A", "B"]),
             "currency": random.choice(["EUR", "USD-W", "JPY"])}
        fee = compute_fee(s)
        assert isinstance(fee, float)
        assert 0.0 <= fee <= s["notional"] * 0.002
